import os, json, time, numpy as np

N = 26
SNAP_C = 'storage/noesis/latest_centers.txt'
SNAP_R = 'storage/noesis/latest_radii.txt'
SHARED = 'storage/shared/appxE_contribs'
OUT_DIR = 'storage/noesis/nmap'
OUT_RES = os.path.join(OUT_DIR, 'results', 'noesis_kkt_slack_compare_v2_1.json')

def _ts():
    return time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())

def _ensure():
    os.makedirs(os.path.join(OUT_DIR, 'results'), exist_ok=True)
    os.makedirs(os.path.join(OUT_DIR, 'freezes'), exist_ok=True)

def load_snapshot():
    try:
        c = np.loadtxt(SNAP_C, dtype=float).reshape(N,2)
        r = np.loadtxt(SNAP_R, dtype=float).reshape(N,)
        return c, r
    except Exception:
        # conservative fallback grid
        centers = []
        rad = 0.08
        for i in range(5):
            for j in range(6):
                if len(centers) < 26:
                    centers.append([0.1 + 0.2*i, 0.1 + 0.15*j])
        return np.array(centers, float), np.full(26, rad, float)

def slacks(c, r):
    x, y = c[:,0], c[:,1]
    s_xL = x - r
    s_xR = 1.0 - x - r
    s_yB = y - r
    s_yT = y + r - 1.0  # alt form not used; keep consistent with others
    s_yT = 1.0 - y - r
    diff = c[:,None,:] - c[None,:,:]
    dist = np.sqrt(np.sum(diff**2, axis=2))
    s_pairs = dist - (r[:,None] + r[None,:])
    return (s_xL, s_xR, s_yB, s_yT), s_pairs

def boundary_active_mask(c, r, tol):
    (s_xL, s_xR, s_yB, s_yT), _ = slacks(c, r)
    return (s_xL <= tol) | (s_xR <= tol) | (s_yB <= tol) | (s_yT <= tol)

def topk_slack(c, r, tol_str, K):
    tol = 1e-9 if tol_str == '1e-9' else 1e-8
    bmask = boundary_active_mask(c, r, tol)
    (_, _ , _, _), sp = slacks(c, r)
    cand = []
    for i in range(N):
        for j in range(i+1, N):
            if not (bmask[i] or bmask[j]):
                cand.append((float(sp[i,j]), i, j))
    cand.sort(key=lambda t: t[0])
    pairs = []
    seen = set()
    for val, i, j in cand:
        if (i,j) in seen:
            continue
        pairs.append([i,j]); seen.add((i,j))
        if len(pairs) >= K:
            break
    return pairs

def read_kkt_file(tol_str, K):
    fname = f'noesis_snapshot_kkt_top_k_{"1e_9" if tol_str=="1e-9" else "1e_8"}.json'
    path = os.path.join(SHARED, fname)
    try:
        data = json.load(open(path, 'r'))
        pairs = data.get('pairs', [])
        # Normalize, enforce i<j, unique, length K
        norm = []
        seen = set()
        for p in pairs:
            if not (isinstance(p, list) and len(p)==2): continue
            i, j = int(p[0]), int(p[1])
            if i > j: i, j = j, i
            if 0 <= i < j < N and (i,j) not in seen:
                norm.append([i,j]); seen.add((i,j))
        return norm[:K], path
    except Exception:
        return [], path

def jaccard(a_pairs, b_pairs):
    A = set(tuple(p) for p in a_pairs)
    B = set(tuple(p) for p in b_pairs)
    if not A and not B: return 1.0
    if not A or not B: return 0.0
    return float(len(A & B))/float(len(A | B))

def spearman_on_intersection(a_pairs, b_pairs):
    # ranks by order
    idx_a = {tuple(p): i for i,p in enumerate(a_pairs)}
    idx_b = {tuple(p): i for i,p in enumerate(b_pairs)}
    inter = [p for p in idx_a if p in idx_b]
    n = len(inter)
    if n < 2: return None, n
    ra = np.array([idx_a[p] for p in inter], dtype=float)
    rb = np.array([idx_b[p] for p in inter], dtype=float)
    ra -= ra.mean(); rb -= rb.mean()
    den = np.sqrt((ra**2).sum()) * np.sqrt((rb**2).sum())
    if den == 0: return None, n
    rho = float((ra*rb).sum()/den)
    return rho, n

def write_outputs(payload):
    _ensure()
    with open(OUT_RES, 'w') as f:
        json.dump(payload, f, indent=2)
    stamp = time.strftime('%Y-%m-%dT%H-%M-%SZ', time.gmtime())
    freeze = os.path.join(OUT_DIR, 'freezes', f'noesis_kkt_slack_compare_v2_1_{stamp}.json')
    with open(freeze, 'w') as f:
        json.dump(payload, f, indent=2)
    return freeze

def construct_packing():
    c, r = load_snapshot()
    res = {'generated_at': _ts(), 'schema': 'v2.1', 'class': 'noesis_snapshot', 'eval_ref': 525, 'by_tol': {}}
    for tol_str, K in [('1e-9', 25), ('1e-8', 15)]:
        kkt_pairs, kkt_path = read_kkt_file(tol_str, K)
        slack_pairs = topk_slack(c, r, tol_str, K)
        jac = jaccard(kkt_pairs, slack_pairs)
        rho, n = spearman_on_intersection(kkt_pairs, slack_pairs)
        res['by_tol'][tol_str] = {
            'K': K,
            'kkt_file': kkt_path,
            'jaccard': jac,
            'spearman_on_intersection': rho,
            'n_intersection': n
        }
    try:
        write_outputs(res)
    except Exception:
        pass
    # Return baseline with tiny shrink
    r_out = np.maximum(r - 1e-9, 1e-12)
    return c.astype(float), r_out.astype(float)
